// Penghitung.java
public class Penghitung {
    public static int total(int[] data) {
        int jumlah = 0;
        for (int d : data) {
            jumlah += d;
        }
        return jumlah;
    }

    public static double rataRata(int[] data) {
        if (data.length == 0) {
            return 0;
        }
        return (double) total(data) / data.length;
    }
}

